    id INTEGER PRIMARY KEY, display_name TEXT NOT NULL, discord_user_id TEXT NOT NULL UNIQUE,
    base_points INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE celebs (
    id INTEGER PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL,
    age_at_pick INTEGER, sheet_age_hint INTEGER, description TEXT,
    is_alive INTEGER NOT NULL DEFAULT 1, died_at TEXT, wiki_url TEXT,
    wiki_url_norm TEXT, wiki_url_de TEXT, wikidata_id TEXT,
    wiki_confirmed INTEGER NOT NULL DEFAULT 0, manual_only INTEGER NOT NULL DEFAULT 0,
    exclude_from_auto INTEGER NOT NULL DEFAULT 0, death_confirmed INTEGER NOT NULL DEFAULT 0,
    death_detected_at TEXT, death_source TEXT, death_list_url TEXT
  );
  CREATE TABLE celeb_review_queue (
    id INTEGER PRIMARY KEY, celeb_id INTEGER NOT NULL UNIQUE,
    proposed_wiki_url TEXT, proposed_age INTEGER, proposed_lang TEXT, proposed_candidates TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
  CREATE TABLE picks (
    player_id INTEGER NOT NULL, celeb_id INTEGER NOT NULL, season_id INTEGER NOT NULL,
    PRIMARY KEY (player_id, celeb_id, season_id)
  );
  CREATE TABLE celeb_aka (celeb_id INTEGER NOT NULL, alias TEXT NOT NULL, PRIMARY KEY (celeb_id, alias));
  CREATE TABLE celeb_blacklist (celeb_id INTEGER NOT NULL, term TEXT NOT NULL, PRIMARY KEY (celeb_id, term));
  CREATE TABLE bonuses (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, points INTEGER NOT NULL);
  CREATE TABLE player_bonuses (player_id INTEGER NOT NULL, bonus_id TEXT NOT NULL, times INTEGER NOT NULL DEFAULT 1, PRIMARY KEY (player_id, bonus_id));
  CREATE TABLE death_awards (
    id INTEGER PRIMARY KEY, celeb_id INTEGER NOT NULL, player_id INTEGER NOT NULL,
    points INTEGER NOT NULL, awarded_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
  CREATE UNIQUE INDEX idx_death_awards_celeb_player ON death_awards(celeb_id, player_id);
  CREATE TABLE celeb_url_wait (admin_user_id TEXT PRIMARY KEY, celeb_id INTEGER NOT NULL, expires_at TEXT NOT NULL);
  CREATE TABLE wiki_seen (entry_id TEXT PRIMARY KEY, lang TEXT, text TEXT, url TEXT, first_seen_at TEXT, announced_at TEXT);
  CREATE TABLE announced_deaths (entry_id TEXT PRIMARY KEY, name TEXT, url TEXT, lang TEXT, announced_at TEXT);
  CREATE TABLE phrase_history (phrase_hash TEXT PRIMARY KEY, used_at TEXT);
  CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
\`);
let boot = 'ok';
